def bsearch(d):
    a, x = d["a"], d["x"]
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == x:
            return mid
        elif a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def merge_sorted(d):
    a, b = d["a"], d["b"]
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

def dedupe(d):
    seen, out = set(), []
    for x in d["a"]:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

