def balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    st = []
    for c in s:
        if c in "([{":
            st.append(c)
        elif c in ")]}":
            if not st or st.pop() != pairs[c]:
                return False
    return not st

def rpn_eval(d):
    toks = d["t"]
    st = []
    for t in toks:
        if t in "+-*/":
            b, a = st.pop(), st.pop()
            st.append({"＋": 0, "+": a + b, "-": a - b, "*": a * b,
                       "/": int(a / b)}[t])
        else:
            st.append(int(t))
    return st[0]

