def min_cost(d):
    # min path sum in grid (right/down only), small grid
    g = d["g"]
    r, c = len(g), len(g[0])
    dp = [[0] * c for _ in range(r)]
    for i in range(r):
        for j in range(c):
            if i == 0 and j == 0:
                dp[i][j] = g[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j - 1] + g[i][j]
            elif j == 0:
                dp[i][j] = dp[i - 1][j] + g[i][j]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + g[i][j]
    return dp[-1][-1]

def lis_len(d):
    a = d["a"]
    if not a:
        return 0
    dp = [1] * len(a)
    for i in range(len(a)):
        for j in range(i):
            if a[j] < a[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

