    import heapq
    return heapq.nlargest(k, a)

def act_max(d):
    iv = sorted(d["iv"], key=lambda x: x[1])
    cnt, end = 0, float("-inf")
    for s, e in iv:
        if s >= end:
            cnt += 1
            end = e
    return cnt

def coins_greedy(d):
    amt, denoms = d["amt"], sorted(d["denoms"], reverse=True)
    out, rem = {}, amt
    for c in denoms:
        out[str(c)], rem = divmod(rem, c)
    return out

